  if(isset($_GET['from'])){$dt=date_create((string)$_GET['from']);if(!$dt)throw new InvalidArgumentException('from must be a valid date/time');$conds[]="$alias.created_at>=?";$params[]=$dt->format('Y-m-d H:i:s');if(!$event){array_pop($conds);$conds[]='p.received_at>=?';}}
