  else{$sql='SELECT p.*,h.node_id,r.received_by_node,r.path_type,r.relay_rssi_dbm,r.rssi_dbm,r.snr_db,c.status delivery_status FROM uplink_packets p JOIN hiker_nodes h ON h.id=p.hiker_node_id LEFT JOIN packet_receptions r ON r.uplink_packet_id=p.id LEFT JOIN downlink_commands c ON c.hiker_node_id=p.hiker_node_id AND c.sequence_number=p.sequence_number';}
  if($conds)$sql.=' WHERE '.implode(' AND ',$conds);$sql.=' ORDER BY '.$alias.'.id DESC LIMIT '.$limit.' OFFSET '.$offset;$q=$pdo->prepare($sql);$q->execute($params);respond([$event?'events':'packets'=>$q->fetchAll(),'limit'=>$limit,'offset'=>$offset]);
